# --- Calendar dates ---
def parse_date(text):
    text=text.strip()
    try:
        if re.fullmatch(r'\d{4}',text):text+='-01-01'
        if re.fullmatch(r'\d{4}-\d{2}',text):text+='-01'
        d=datetime.datetime.fromisoformat(text.replace('Z','+00:00'))
        if d.tzinfo is None:d=d.replace(tzinfo=datetime.timezone.utc)
        return int(d.timestamp()*1000)
    except (ValueError,OverflowError):
        import email.utils
        try:return int(email.utils.parsedate_to_datetime(text).timestamp()*1000)
        except:return math.nan

def date_ms(parts,fix_year=True):
    values=[integer(x) for x in parts]
