    year=values[0] if values else 0;month=values[1] if len(values)>1 else 0;day=values[2] if len(values)>2 else 1
    if fix_year and 0<=year<=99:year+=1900
    hour=values[3] if len(values)>3 else 0;minute=values[4] if len(values)>4 else 0;sec=values[5] if len(values)>5 else 0;ms=values[6] if len(values)>6 else 0
    year+=month//12;month=month%12+1
    try:
        d=datetime.datetime(year,month,1,tzinfo=datetime.timezone.utc)+datetime.timedelta(days=day-1,hours=hour,minutes=minute,seconds=sec,milliseconds=ms)
        return int(d.timestamp()*1000)
    except:return math.nan

