"""Early syntactic checks performed before any program side effects."""
from .syntax import Node, Token, ParseError, Lexer

def validate(tree,source,filename,strict=False):
    tokens=Lexer(source,filename).lex()
    def fail(msg,tok):raise ParseError(msg,tok,filename)
    def following(node):
        for t in tokens:
            if t.start>=node.tok.end:return t
        return tokens[-1]
    def names(p):
        if not p:return []
        if p.kind=='id':return [p]
        if p.kind in ('rest','spread','default'):return names(p.args[0])
        if p.kind=='assign':return names(p.args[1])
        if p.kind in ('array','arraypattern'):return [x for pp in p.args[0] for x in names(pp)]
        if p.kind in ('object','objectpattern'):return [x for item in p.args[0] for x in names(item[-1])]
        return []
    def strict_body(node):
        if node.kind!='block':return None
        for st in node.args[0]:
            if st.kind!='exprstmt' or st.args[0].kind!='literal' or not isinstance(st.args[0].args[0],str):break
            if st.args[0].args[0]=='use strict':return st.args[0].tok
        return None
    def walk(n,strict=False,loops=0,switches=0,labels=None,forinit=False):
        if n is None or not isinstance(n,Node):return
        labels=labels or {};k=n.kind;a=n.args
        if k=='block':
            stt=strict_body(n);strict=strict or bool(stt);lex={};var={}
            for st in a[0]:
                if st.kind=='exportdecl':st=st.args[0]
                if st.kind=='var':
                    for pat,init in st.args[1]:
                        for ident in names(pat):
                            key=ident.args[0]
                            if key in lex or st.args[0]!='var' and key in var:fail('invalid redefinition of lexical identifier',following(ident))
                            (var if st.args[0]=='var' else lex)[key]=ident
                if st.kind=='class' and st.declaration:
                    if st.args[0] in lex:fail('invalid redefinition of lexical identifier',st.tok)
                    lex[st.args[0]]=st
            for st in a[0]:walk(st,strict,loops,switches,labels)
            return
        if k=='function':
            name,pars,body=a;localstrict=strict or bool(strict_body(body));seen=set()
            if localstrict or n.arrow or any(p.kind!='id' for p in pars):
                for pat in pars:
                    for ident in names(pat):
                        if ident.args[0] in seen:fail('duplicate argument names not allowed in this context',strict_body(body) or ident.tok)
                        seen.add(ident.args[0])
            walk(body,localstrict);return
        if k=='class':
            for key,mode,val,static in a[2]:walk(val,True)
            return
        if k=='with' and strict:fail('invalid keyword: with',n.tok)
        if k=='var':
            for pat,init in a[1]:
                if a[0]=='const' and init is None and not forinit:fail('missing initializer for const variable',following(pat))
                walk(init,strict,loops,switches,labels)
            return
        if k in ('break','continue'):
            if a[0]:
                if a[0] not in labels:fail('break/continue label not found',following(n))
            elif k=='break' and not loops and not switches:fail('break must be inside loop or switch',following(n))
            elif k=='continue' and not loops:fail('continue must be inside loop',following(n))
            return
        if k=='label':
            if a[0] in labels:fail('duplicate label name',n.tok)
            newlabels=dict(labels);newlabels[a[0]]=True;walk(a[1],strict,loops,switches,newlabels);return
        if k in ('for','forof','forin'):
            walk(a[0],strict,loops,switches,labels,k!='for')
            for x in a[1:]:walk(x,strict,loops+1,switches,labels)
            return
        if k in ('do','while'):
            for x in a:walk(x,strict,loops+1,switches,labels)
            return
        if k=='switch':
            walk(a[0],strict,loops,switches,labels)
            for cond,body in a[1]:
                walk(cond,strict,loops,switches+1,labels)
                for st in body:walk(st,strict,loops,switches+1,labels)
            return
        if k=='assign':
            if a[1].kind not in ('id','member','array','object'):fail('invalid assignment left-hand side',following(n))
        if k=='unary' and a[0] in ('++','--') and a[1].kind not in ('id','member'):fail('invalid increment/decrement operand',n.tok)
        if k=='unary' and a[0]=='delete' and a[1].kind=='id' and strict:fail('cannot delete a direct reference in strict mode',n.tok)
        def each(x):
            if isinstance(x,Node):walk(x,strict,loops,switches,labels)
            elif isinstance(x,(tuple,list)):
                for v in x:each(v)
        for x in a:each(x)
    walk(tree,strict)
